// ---------- atomic helpers ----------
function T(str, size, style, color, opts={}) {
  const t = figma.createText();
  t.fontName = { family:'Inter', style };
  t.characters = str;
  t.fontSize = size;
  t.fills = solid(color);
  if (opts.lh) t.lineHeight = { value: opts.lh, unit:'PERCENT' };
  if (opts.ls !== undefined) t.letterSpacing = { value: opts.ls, unit:'PERCENT' };
  if (opts.w) { t.textAutoResize = 'NONE'; t.resize(opts.w, t.height); }
  else t.textAutoResize = 'HEIGHT';
  return t;
}
function frame(name, w, h, fill) {
  const f = figma.createFrame();
  f.name = name; f.resize(w, h);
  if (fill === null) f.fills = []; else f.fills = solid(fill === undefined ? C.white : fill);
  f.clipsContent = true;
  return f;
}
