// pin/unpin one overlay into an absolute parent at x,y
function pin(abs, child, x, y, opts={}) {
  abs.appendChild(child);
  child.layoutPositioning = 'ABSOLUTE';
  child.x = x; child.y = y;
  if (opts.order === 'bottom') abs.insertChild(0, child);
  return child;
}

