// base: bg, status bar, home indicator
async function base(frameNode, opts={}) {
  const { bar='light', indicator=true, overlayShell=false } = opts;
  frameNode.itemSpacing = 0; frameNode.paddingTop = 0; frameNode.paddingRight = 0; frameNode.paddingBottom = 0; frameNode.paddingLeft = 0;
  // bg as absolute layer
  const bg = rect(375, frameNode.height, opts.bg || C.bg);
  frameNode.appendChild(bg);
  const sb = await inst('StatusBar'); sb.x = 0; sb.y = 0;
  const hi = indicator ? await inst('HomeIndicator') : null;
  if (hi) { hi.x = 0; hi.y = frameNode.height - 34; }
  if (overlayShell) {
    frameNode.appendChild(sb); if (hi) frameNode.appendChild(hi);
    if (bar === 'light-content') { sb.opacity = 1; }
  } else {
    // content flow in autolayout: statusbar, content, home indicator handled per screen
    frameNode.insertChild(0, sb);
    if (hi) frameNode.appendChild(hi);
  }
  return { sb, hi };
}

