// Inspect key components' internal structure & text to verify defaults; check icon fills for recoloring
const workspace = await figma.getNodeByIdAsync('4:2');
const lib = workspace.findOne(n=>n.name==='Placoo · Components');
function dump(n,depth=0){
  const o={name:n.name,type:n.type};
  if(n.type==='TEXT'){ o.characters=n.characters; o.fontName=n.fontName; o.fontSize=n.fontSize; }
  if('layoutMode' in n && n.layoutMode!=='NONE') o.layout=n.layoutMode;
  if(n.type==='INSTANCE') o.ref=n.name;
  if(depth<4 && 'children' in n) o.children=n.children.map(c=>dump(c,depth+1));
  return o;
}
const names=['Button / Primary','Card / Property','SearchBar','TabBar','Field / Username','Field / Phone','Field / Password','Stepper','Slider / PriceRange','Row / Conversation','Bubble / Sent','Row / Payment','Row / ProfileMenu','Header / Nav','Segment / RentBuy','Card / Destination','Card / Article','Pin / Price Default'];
const out={};
for(const n of names){ const c=lib.findOne(x=>x.name===n&&x.type==='COMPONENT'); if(c) out[n]=dump(c); }
// also check a media icon instance structure for fill recolor
const icon = await figma.getNodeByIdAsync('1:300'); // Icon_Arrow_Left component
out._iconArrow = dump(icon,3);
const photo = await figma.getNodeByIdAsync('1:356'); // Photo_Onboarding_1
out._photo = dump(photo,2);
const mapC = await figma.getNodeByIdAsync('1:346');
out._map = dump(mapC,2);
const statusBar = await figma.getNodeByIdAsync('1:33');
out._statusBar = dump(statusBar,2);
return out;

